use serde_json::{Value,json};
#[tauri::command]
pub fn available_printers()->Result<Value,String>{
 #[cfg(target_os="windows")]unsafe{
  use windows::Win32::Graphics::Printing::{EnumPrintersW,GetDefaultPrinterW,PRINTER_ENUM_LOCAL,PRINTER_ENUM_CONNECTIONS,PRINTER_INFO_4W};use windows::core::{PCWSTR,PWSTR};
  let mut needed=0;let mut count=0;let _=EnumPrintersW(PRINTER_ENUM_LOCAL|PRINTER_ENUM_CONNECTIONS,PCWSTR::null(),4,None,&mut needed,&mut count);if needed>16*1024*1024{return Err("Printer list exceeds limit".into());}let mut names=Vec::new();if needed>0{let mut data=vec![0u8;needed as usize];EnumPrintersW(PRINTER_ENUM_LOCAL|PRINTER_ENUM_CONNECTIONS,PCWSTR::null(),4,Some(&mut data),&mut needed,&mut count).map_err(|e|e.to_string())?;for i in 0..count as usize{let item=std::ptr::read_unaligned(data.as_ptr().add(i*std::mem::size_of::<PRINTER_INFO_4W>()).cast::<PRINTER_INFO_4W>());if !item.pPrinterName.is_null(){if let Ok(name)=item.pPrinterName.to_string(){names.push(name);}}}}
  let mut length=0;let _=GetDefaultPrinterW(None,&mut length);let mut name=vec![0u16;length as usize];let default=if length>0&&GetDefaultPrinterW(Some(PWSTR(name.as_mut_ptr())),&mut length).as_bool(){Some(String::from_utf16_lossy(&name[..name.iter().position(|c|*c==0).unwrap_or(name.len())]))}else{None};return Ok(json!({"printers":names,"default":default,"native":true}));
 }
 #[cfg(not(target_os="windows"))]Ok(json!({"printers":[],"default":null,"native":false}))
}
#[tauri::command]
pub async fn print_document(app:tauri::AppHandle,html:String,printer:String,landscape:bool,color:bool,copies:u16,pages:String)->Result<(),String>{
 if copies==0||copies>999||printer.trim().is_empty()||printer.len()>2000||pages.len()>500||!pages.bytes().all(|c|c.is_ascii_digit()||c==b','||c==b'-'||c==b' '){return Err("Invalid print options".into());}
 #[cfg(target_os="windows")]{render(app,html,printer,landscape,color,copies,pages).await}
 #[cfg(not(target_os="windows"))]{let _=(app,html,printer,landscape,color,copies,pages);Err("Native printing is unavailable on this platform".into())}
}
#[cfg(target_os="windows")]
async fn render(app:tauri::AppHandle,html:String,printer:String,landscape:bool,color:bool,copies:u16,pages:String)->Result<(),String>{
 use std::{fs,sync::{Arc,atomic::{AtomicBool,Ordering},mpsc},time::{Duration,SystemTime,UNIX_EPOCH}};use tauri::{WebviewWindowBuilder,WebviewUrl,webview::PageLoadEvent};use windows::core::{HSTRING,Interface};
 use webview2_com::{PrintCompletedHandler,Microsoft::Web::WebView2::Win32::{ICoreWebView2_16,ICoreWebView2Environment6,ICoreWebView2PrintSettings2,COREWEBVIEW2_PRINT_ORIENTATION_LANDSCAPE,COREWEBVIEW2_PRINT_ORIENTATION_PORTRAIT,COREWEBVIEW2_PRINT_COLOR_MODE_COLOR,COREWEBVIEW2_PRINT_COLOR_MODE_GRAYSCALE,COREWEBVIEW2_PRINT_STATUS_SUCCEEDED}};
 if html.len()>128*1024*1024{return Err("Print document exceeds limit".into());}let stamp=SystemTime::now().duration_since(UNIX_EPOCH).map_err(|e|e.to_string())?.as_nanos();let file=std::env::temp_dir().join(format!("openhau-print-{stamp}.html"));let csp="<meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'none'; img-src data:; style-src 'unsafe-inline'; font-src data:; base-uri 'none'; form-action 'none'\">";let secured=if html.contains("<head>"){html.replacen("<head>",&format!("<head>{csp}"),1)}else{format!("{csp}{html}")};fs::write(&file,secured).map_err(|e|e.to_string())?;
 let (tx,rx)=mpsc::channel::<Result<(),String>>();let started=Arc::new(AtomicBool::new(false));let url=tauri::Url::from_file_path(&file).map_err(|_|"Invalid print path")?;
 let result=WebviewWindowBuilder::new(&app,format!("print-{stamp}"),WebviewUrl::External(url)).visible(false).skip_taskbar(true).inner_size(1100.0,900.0).on_page_load(move|window,payload|{if !matches!(payload.event(),PageLoadEvent::Finished)||started.swap(true,Ordering::SeqCst){return;}let tx=tx.clone();let failure=tx.clone();let printer=printer.clone();let pages=pages.clone();if let Err(e)=window.with_webview(move|webview|unsafe{let begin=(||->windows::core::Result<()>{let core=webview.controller().CoreWebView2()?.cast::<ICoreWebView2_16>()?;let environment=webview.environment().cast::<ICoreWebView2Environment6>()?;let settings=environment.CreatePrintSettings()?;settings.SetOrientation(if landscape{COREWEBVIEW2_PRINT_ORIENTATION_LANDSCAPE}else{COREWEBVIEW2_PRINT_ORIENTATION_PORTRAIT})?;settings.SetShouldPrintBackgrounds(true)?;settings.SetShouldPrintHeaderAndFooter(false)?;settings.SetMarginTop(0.0)?;settings.SetMarginBottom(0.0)?;settings.SetMarginLeft(0.0)?;settings.SetMarginRight(0.0)?;let extended=settings.cast::<ICoreWebView2PrintSettings2>()?;extended.SetPrinterName(&HSTRING::from(printer))?;extended.SetColorMode(if color{COREWEBVIEW2_PRINT_COLOR_MODE_COLOR}else{COREWEBVIEW2_PRINT_COLOR_MODE_GRAYSCALE})?;extended.SetCopies(copies as i32)?;if !pages.trim().is_empty(){extended.SetPageRanges(&HSTRING::from(pages))?;}let complete=tx.clone();core.Print(&settings,&PrintCompletedHandler::create(Box::new(move|status,result|{let result=if result==COREWEBVIEW2_PRINT_STATUS_SUCCEEDED{status.map_err(|e|e.to_string())}else{Err("Printer could not complete the print job".into())};let _=complete.send(result);Ok(())})))?;Ok(())})();if let Err(e)=begin{let _=tx.send(Err(e.to_string()));}}){let _=failure.send(Err(e.to_string()));}}).build();
 let window=match result{Ok(window)=>window,Err(e)=>{let _=fs::remove_file(&file);return Err(e.to_string());}};let result=tauri::async_runtime::spawn_blocking(move||rx.recv_timeout(Duration::from_secs(120)).map_err(|e|e.to_string()).and_then(|r|r)).await.map_err(|e|e.to_string()).and_then(|r|r);let _=window.destroy();let _=fs::remove_file(file);result
}
